{
 "didatica": [
  {
   "campo": "resolucao.pista",
   "depois": "A cédula teme ser abandonada. No mundo do banco, qual palavra da fala também nomeia o que o dinheiro guardado rende?",
   "motivo": "Frase mais clara e sem entregar a palavra."
  },
  {
   "campo": "resolucao.antes.simbolos",
   "depois": [
    ["bank", "banco, a instituição financeira"],
    ["lose", "perder"],
    ["as long as", "contanto que, desde que"],
    ["interest", "interesse (atenção, afeto) e também juros (dinheiro que o banco paga por quem deposita)"],
    ["cartum", "desenho de humor, com imagem e fala"],
    ["cédula", "nota de dinheiro"],
    ["duplo sentido", "palavra que pode ser entendida de duas maneiras"]
   ],
   "motivo": "Explica 'juros' e inclui termos usados na resolução."
  },
  {
   "campo": "resolucao.passos[0].conta",
   "depois": "humor vem de qual palavra?",
   "motivo": "Conta curta e que cabe na tela; a explicação fica no porque."
  },
  {
   "campo": "resolucao.passos[2].conta",
   "depois": "cédula sorrindo + sacos de $",
   "motivo": "Cabe em ~30 caracteres."
  },
  {
   "campo": "resolucao.passos[3].porque",
   "depois": "Na frase, “perder o interesse” é sentimento: deixar de gostar. No banco, “interest” são os juros que o dinheiro rende. A cédula brinca com os dois sentidos.",
   "motivo": "Frases mais curtas e diretas."
  },
  {
   "campo": "resolucao.passos[4].porque",
   "depois": "A nota diz que o banco não vai perder o interesse nela. Dinheiro depositado também rende juros (interest). Só essa palavra tem as duas leituras.",
   "motivo": "Simplifica e tira a frase longa."
  },
  {
   "campo": "resolucao.checagem",
   "depois": "Troque “interest” por “juros”: “eles não vão perder os juros em mim”. Soa estranho e engraçado, porque o dinheiro rende juros no banco. Com “bank”, “lose”, “long” ou “as”, nenhuma troca cria um segundo sentido ligado a dinheiro.",
   "motivo": "Texto mais claro, sem frase ambígua."
  }
 ],
